INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('تورينو كامب', 'Torino Camp', 'camp', 'budget', 'كامب cozy وهادي في قلب ممشى دهب السياحي — المكان المثالي للباكبكرز والمسافرين اللي بيدوروا على vibes حقيقية مش تكلفة. خطوات من البحر وكل كافيهات اللايت هاوس، وغرف مريحة ونضيفة بديكور boho modern chic.', 'A cozy, laid-back camp in the heart of Dahab''s promenade — the perfect spot for backpackers and travelers looking for real vibes, not just a room. Steps from the sea and all the Lighthouse cafes, with comfy, clean boho-modern rooms.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80']::TEXT[], 4.2, 'الممشى السياحي · اللايت هاوس · دهب', 'الممشى السياحي · اللايت هاوس · دهب', 'Promenade · Lighthouse · Dahab', 28.5092, 34.5185, ARRAY['واي فاي', 'قعدات بدوية', 'قريب من البحر', 'تكييف']::TEXT[], ARRAY['WiFi', 'Bedouin Seating', 'Near Beach', 'AC']::TEXT[], 650, 2650, 3200, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('فندق أنتيكا', 'Antika Hotel', 'hotel', 'budget', 'فندق صغير بحمام سباحة في قلب الممشى — جنب محطة Go Bus. قعدات بدوية مريحة بروح دهب الأصيلة، وغرف نظيفة وبسيطة. مناسب جداً للجروبات والصحاب اللي عايزين مكان نضيف وقريب من كل حاجة.', 'A small hotel with a pool right in the heart of the promenade — next to Go Bus station. Comfortable Bedouin-style seating with authentic Dahab spirit, clean simple rooms. Perfect for groups who want a clean place close to everything.', ARRAY['https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&q=80']::TEXT[], 4, 'الممشى السياحي · جنب Go Bus · دهب', 'الممشى السياحي · جنب Go Bus · دهب', 'Promenade · Near Go Bus · Dahab', 28.5092, 34.5185, ARRAY['حمام سباحة', 'واي فاي', 'قعدات بدوية', 'تكييف']::TEXT[], ARRAY['Swimming Pool', 'WiFi', 'Bedouin Seating', 'AC']::TEXT[], 800, 3300, 4100, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('موخيتو بالم', 'Mojito Palm', 'hotel', 'budget', 'صف أول على البحر مباشرة — الكافيه والإفطار بيطلوا على المياه الفيروزية. جنب الكوبري الخشبي أشهر spot تصوير في دهب. غرف مريحة وإطلالة بحر، والفطار اختياري في كافيه موخيتو الشهير.', 'First row directly on the sea — the café and breakfast overlook turquoise waters. Next to the wooden bridge, Dahab''s most famous photo spot. Comfortable rooms with sea view, optional breakfast at the famous Mojito Café.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.3, 'الممشى السياحي · صف أول بحر · اللايت هاوس', 'الممشى السياحي · صف أول بحر · اللايت هاوس', 'Promenade · First Row · Lighthouse', 28.5092, 34.5185, ARRAY['إطلالة بحر مباشرة', 'كافيه على البحر', 'واي فاي', 'تكييف']::TEXT[], ARRAY['Direct Sea View', 'Seaside Café', 'WiFi', 'AC']::TEXT[], 650, 2650, 3200, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('فندق موخيتو', 'Mojito Hotel Standard', 'hotel', 'standard', 'غرف فندقية حديثة بأعلى مستوى من الراحة في موقع اللايت هاوس — صف أول بحر. كافيه موخيتو الشهير مباشرة تحتك، والفطار اختياري بتكلفة بسيطة على البحر. من أشهر أماكن الإقامة وأكثرها طلباً في دهب.', 'Modern hotel rooms with top-tier comfort in the Lighthouse area — first row on the sea. The famous Mojito Café right below, optional breakfast at a small cost right on the water. One of Dahab''s most requested stays.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.4, 'اللايت هاوس · صف أول بحر · دهب', 'اللايت هاوس · صف أول بحر · دهب', 'Lighthouse · First Row · Dahab', 28.5092, 34.5185, ARRAY['غرف حديثة', 'إطلالة بحر', 'واي فاي', 'تكييف', 'كافيه']::TEXT[], ARRAY['Modern Rooms', 'Sea View', 'WiFi', 'AC', 'Café']::TEXT[], 800, 3100, 3750, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('دلتا دهب', 'Delta Dahab', 'hotel', 'standard', 'فندق بحمام سباحة في قلب الممشى السياحي — مش هتحتاج تتحرك كتير عشان توصل لأي حاجة. فطار ومشروبات شاملة طول اليوم، وموقع مركزي يخليك في نص الحدث. مثالي للي عايزين راحة وقرب من كل حاجة.', 'A hotel with a swimming pool in the heart of the promenade — you won''t need to go far for anything. Breakfast and drinks included all day, central location keeps you in the middle of everything. Ideal for those who want comfort and proximity.', ARRAY['https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&q=80']::TEXT[], 4.2, 'قلب الممشى السياحي · دهب', 'قلب الممشى السياحي · دهب', 'Heart of Promenade · Dahab', 28.5092, 34.5185, ARRAY['حمام سباحة', 'فطار ومشروبات', 'واي فاي', 'تكييف', 'موقع مركزي']::TEXT[], ARRAY['Swimming Pool', 'Breakfast & Drinks', 'WiFi', 'AC', 'Central Location']::TEXT[], 900, 3450, 4250, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('ديزرت هوتيل', 'Desert Hotel', 'hotel', 'standard', 'طابع بدوي أصيل وروح سيناء الحقيقية في فندق هادي بعيد عن صخب الممشى — لكن قريب من كل حاجة. تجربة مختلفة ما بين صحراء دهب وشواطئها، للمسافر اللي بيدور على هدوء وخصوصية.', 'Authentic Bedouin character and real Sinai spirit in a quiet hotel away from the promenade buzz — yet close to everything. A different experience between Dahab''s desert and beaches, for the traveler seeking peace and privacy.', ARRAY['https://images.unsplash.com/photo-1451337516015-6b6e9a44a8a3?w=800&q=80', 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80']::TEXT[], 4.3, 'دهب · طابع بدوي · قريب من البحر', 'دهب · طابع بدوي · قريب من البحر', 'Dahab · Bedouin Style · Near Beach', 28.5092, 34.5185, ARRAY['هدوء وخصوصية', 'طابع بدوي', 'واي فاي', 'تكييف', 'قريب من البحر']::TEXT[], ARRAY['Quiet & Private', 'Bedouin Style', 'WiFi', 'AC', 'Near Beach']::TEXT[], 900, 3500, 4400, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('بيت كابانا (شقق خاصة)', 'Cabana House (Private Apartment)', 'chalet', 'standard', 'شقق خاصة بالكامل في قلب العسلة الهادية — مطبخ، صالة، وخصوصية تامة. 5 دقائق مشي وانت على البحر. الفرد التالت والرابع بنص السعر — مثالي للجروبات والعائلات اللي عايزة مساحتها واستقلاليتها.', 'Fully private apartments in the quiet Assala area — kitchen, living room, and complete privacy. 5 minutes walk to the beach. 3rd and 4th person at half price — ideal for groups and families who want their own space.', ARRAY['https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&q=80', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80']::TEXT[], 4.4, 'العسلة · 5 دقائق على البحر · دهب', 'العسلة · 5 دقائق على البحر · دهب', 'Assala · 5min to Beach · Dahab', 28.5092, 34.5185, ARRAY['شقة كاملة', 'مطبخ مجهز', 'خصوصية تامة', 'واي فاي', 'قريب من البحر']::TEXT[], ARRAY['Full Apartment', 'Equipped Kitchen', 'Full Privacy', 'WiFi', 'Near Beach']::TEXT[], 850, 3300, 4100, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('صن سيت لاكجري هوتيل', 'Sunset Luxury Hotel', 'hotel', 'standard', 'فندق راقي في قلب الممشى السياحي — اسمه مش صدفة: أحلى إطلالة غروب في دهب من التراس والغرف. فطار يومي شامل يبدأ يومك على راحتك، وغرف فندقية مريحة بديكور دافئ وعصري.', 'An upscale hotel in the heart of the promenade — the name is no coincidence: the best sunset view in Dahab from the terrace and rooms. Daily breakfast included to start your day right, comfortable rooms with warm modern decor.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80']::TEXT[], 4.5, 'الممشى السياحي · إطلالة الغروب · دهب', 'الممشى السياحي · إطلالة الغروب · دهب', 'Promenade · Sunset View · Dahab', 28.5092, 34.5185, ARRAY['فطار يومي شامل', 'إطلالة غروب', 'واي فاي', 'تكييف', 'تراس']::TEXT[], ARRAY['Daily Breakfast', 'Sunset View', 'WiFi', 'AC', 'Terrace']::TEXT[], 1050, 4100, 5000, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('موخيتو بانوراما', 'Mojito Panorama Sea View', 'hotel', 'premium', 'Panoramic Sea View مباشر من الغرفة — من أكتر الغرف طلباً في دهب كلها. إطلالة 180 درجة على البحر الأحمر والجبال، وتفاصيل فندقية راقية. الفطار اختياري بتكلفة إضافية مع إطلالة لا توصف.', 'Direct Panoramic Sea View from your room — one of the most requested rooms in all of Dahab. 180-degree views of the Red Sea and mountains, with refined hotel details. Optional breakfast at extra cost with an indescribable view.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.7, 'اللايت هاوس · بانوراما سي فيو · دهب', 'اللايت هاوس · بانوراما سي فيو · دهب', 'Lighthouse · Panorama Sea View · Dahab', 28.5092, 34.5185, ARRAY['بانوراما سي فيو', 'غرف فاخرة', 'واي فاي', 'تكييف', 'كافيه']::TEXT[], ARRAY['Panorama Sea View', 'Luxury Rooms', 'WiFi', 'AC', 'Café']::TEXT[], 1100, 4350, 5550, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('موخيتو تيراس', 'Mojito Terrace Sea View', 'hotel', 'premium', 'أعلى مستوى في موخيتو — تراس خاص بيطل مباشرة على البحر الأحمر. الغرفة مصممة للعرسان والأزواج اللي بيدوروا على لحظة خاصة. الفطار اختياري بتكلفة إضافية مع sunrise على البحر من تراسك الخاص.', 'The highest tier at Mojito — private terrace overlooking the Red Sea directly. The room is designed for honeymooners and couples seeking a special moment. Optional breakfast at extra cost with sunrise on the sea from your private terrace.', ARRAY['https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.8, 'اللايت هاوس · تراس خاص على البحر · دهب', 'اللايت هاوس · تراس خاص على البحر · دهب', 'Lighthouse · Private Terrace · Dahab', 28.5092, 34.5185, ARRAY['تراس خاص', 'إطلالة بحر مباشرة', 'غرفة مميزة للعرسان', 'واي فاي', 'تكييف']::TEXT[], ARRAY['Private Terrace', 'Direct Sea View', 'Honeymoon Room', 'WiFi', 'AC']::TEXT[], 1200, 4600, 5900, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('فندق نسيمة', 'Nesima Hotel', 'hotel', 'premium', '4 نجوم — من أشهر وأعرق فنادق دهب. حمام سباحة ومطعم على البحر مباشرة، ومركز غوص Nesima الشهير. الغرف أنيقة وواسعة، ومناسب جداً للعائلات والغواصين اللي بيدوروا على إقامة مريحة بمستوى عالي.', '4 stars — one of Dahab''s most famous and established hotels. Swimming pool and restaurant directly on the sea, plus the renowned Nesima Dive Center. Elegant, spacious rooms, ideal for families and divers seeking high-quality comfort.', ARRAY['https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.5, 'الممشى السياحي · صف أول · دهب', 'الممشى السياحي · صف أول · دهب', 'Promenade · First Row · Dahab', 28.5092, 34.5185, ARRAY['حمام سباحة', 'مطعم على البحر', 'مركز غوص', 'واي فاي', 'تكييف', 'فطار']::TEXT[], ARRAY['Swimming Pool', 'Seaside Restaurant', 'Dive Center', 'WiFi', 'AC', 'Breakfast']::TEXT[], 1200, 4800, 6000, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('أسالة سي فيو', 'Assala Sea View', 'chalet', 'premium', 'استوديوهات وشاليهات وأبارتمنتات مباشرة على البحر في العسلة الهادية — أبعد عن ضوضاء الممشى، أقرب للـ vibes الحقيقية. الفرد التالت والرابع بنص السعر — مثالي للجروبات والعرسان.', 'Studios, chalets, and apartments directly on the sea in quiet Assala — away from the promenade noise, closer to the real vibes. 3rd and 4th person at half price — ideal for groups and honeymooners.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80']::TEXT[], 4.6, 'العسلة · مباشرة على البحر · دهب', 'العسلة · مباشرة على البحر · دهب', 'Assala · Directly on Beach · Dahab', 28.5092, 34.5185, ARRAY['مباشرة على البحر', 'مطبخ مجهز', 'خصوصية', 'واي فاي', 'تكييف']::TEXT[], ARRAY['Beachfront', 'Equipped Kitchen', 'Privacy', 'WiFi', 'AC']::TEXT[], 1400, 5600, 6600, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('كانيون / نوبيا آيلاند', 'Canyon / Nubia Island', 'hotel', 'lagoon', 'شاطئ رملي طبيعي في منطقة اللاجونا الخلابة — بعيد عن زحمة الممشى، قريب من الطبيعة. بوفيه فطار أوبن متنوع ومريح، وهدوء تام ما بين البحر والجبال. تجربة مختلفة لمن يريد دهب أخرى.', 'Natural sandy beach in the stunning Laguna area — away from the promenade crowds, close to nature. Open buffet breakfast, varied and comfortable, with total peace between the sea and mountains. A different experience for those seeking another Dahab.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.3, 'اللاجونا · شاطئ رملي · دهب', 'اللاجونا · شاطئ رملي · دهب', 'Laguna · Sandy Beach · Dahab', 28.5092, 34.5185, ARRAY['شاطئ رملي', 'بوفيه فطار', 'هدوء تام', 'واي فاي', 'تكييف']::TEXT[], ARRAY['Sandy Beach', 'Breakfast Buffet', 'Total Quiet', 'WiFi', 'AC']::TEXT[], 1050, 4200, 5200, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('باندا دهب ريزورت', 'Panda Dahab Resort', 'hotel', 'lagoon', 'ريزورت على شاطئ رملي في اللاجونا — أجواء رايقة وخدمة فندقية متكاملة. فطار شامل يومياً، ومساحات خضراء واسعة. مناسب للعائلات والجروبات اللي عايزة تستمتع بالبحر والهدوء بعيد عن الصخب.', 'Resort on a sandy beach in the Laguna — chill vibes with full hotel service. Daily breakfast included, spacious green areas. Suitable for families and groups who want to enjoy the sea and tranquility away from the buzz.', ARRAY['https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.4, 'اللاجونا · شاطئ رملي · دهب', 'اللاجونا · شاطئ رملي · دهب', 'Laguna · Sandy Beach · Dahab', 28.5092, 34.5185, ARRAY['شاطئ رملي', 'فطار شامل', 'مساحات خضراء', 'واي فاي', 'تكييف', 'مناسب للعائلات']::TEXT[], ARRAY['Sandy Beach', 'Breakfast Included', 'Green Areas', 'WiFi', 'AC', 'Family-Friendly']::TEXT[], 1200, 4800, 6000, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('جنة سيناء ريزورت', 'Ganet Sinai Resort', 'hotel', 'lagoon', 'صف أول في اللاجونا — مباشر على الشاطئ الرملي بمياه فيروزية. بوفيه فطار أوبن يومياً واسع ومتنوع، وغرف Deluxe Sea View متاحة بسعر إضافي. من أجمل مواقع اللاجونا وأكثرها طلباً.', 'First row in the Laguna — directly on the sandy beach with turquoise waters. Daily open breakfast buffet, wide and varied. Deluxe Sea View rooms available at extra cost. One of the most beautiful and requested spots in the Laguna.', ARRAY['https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&q=80']::TEXT[], 4.5, 'اللاجونا · صف أول · دهب', 'اللاجونا · صف أول · دهب', 'Laguna · First Row · Dahab', 28.5092, 34.5185, ARRAY['صف أول بحر', 'بوفيه فطار', 'ديلوكس سي فيو', 'واي فاي', 'تكييف']::TEXT[], ARRAY['First Row Beach', 'Breakfast Buffet', 'Deluxe Sea View', 'WiFi', 'AC']::TEXT[], 1300, 5200, 6600, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('إيكوتيل باي فيو', 'Ecotel Bay View Resort', 'hotel', 'lagoon', '4 نجوم في منطقة الثري بولز — من أجمل بقاع دهب وأكثرها هدوءاً. Half Board يومياً يشمل فطار وعشاء في الريزورت، وشاطئ بحري مباشر على مياه الثري بولز الفيروزية. تجربة فندقية راقية في موقع استثنائي.', '4 stars in the Three Pools area — one of Dahab''s most beautiful and peaceful spots. Daily Half Board with breakfast and dinner at the resort, direct beach on the turquoise waters of Three Pools. Upscale hotel experience in an exceptional location.', ARRAY['https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.7, 'الثري بولز · صف أول · دهب', 'الثري بولز · صف أول · دهب', 'Three Pools · First Row · Dahab', 28.5092, 34.5185, ARRAY['Half Board', 'شاطئ خاص', '4 نجوم', 'واي فاي', 'تكييف', 'مطعم']::TEXT[], ARRAY['Half Board', 'Private Beach', '4 Stars', 'WiFi', 'AC', 'Restaurant']::TEXT[], 2300, 9100, 11800, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('ريتاك قناي', 'Retac Qunay Resort', 'hotel', 'lagoon', '5 نجوم في أفضل موقع — بين الثري بولز واللاجونا. Half Board يومياً في مطعم ريزورت متميز، وغرف Deluxe وSea View. تجربة فندقية فاخرة تجمع بين أفضل ما في دهب: البحر، الهدوء، والخدمة الممتازة.', '5 stars in the best location — between Three Pools and the Laguna. Daily Half Board at a distinguished resort restaurant, Deluxe and Sea View rooms. A luxurious hotel experience combining the best of Dahab: sea, tranquility, and excellent service.', ARRAY['https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.8, 'بين الثري بولز واللاجونا · دهب', 'بين الثري بولز واللاجونا · دهب', 'Between Three Pools & Laguna · Dahab', 28.5092, 34.5185, ARRAY['5 نجوم', 'Half Board', 'ديلوكس سي فيو', 'واي فاي', 'مسبح', 'مطعم فاخر']::TEXT[], ARRAY['5 Stars', 'Half Board', 'Deluxe Sea View', 'WiFi', 'Pool', 'Fine Dining']::TEXT[], 2400, 9600, 12400, true);
INSERT INTO accommodations (name_ar, name_en, type, tier, description_ar, description_en, images, rating, location, location_ar, location_en, latitude, longitude, amenities_ar, amenities_en, price_per_night, price_4day, price_5day, is_active) VALUES ('دهب لاجون ريزورت', 'Dahab Lagoon Resort', 'hotel', 'lagoon', 'الأفخم والأرقى في دهب — 5 نجوم على شاطئ رملي خاص في اللاجونا الساحرة. Half Board في مطعم مستوى عالمي على البحر، وفيلات وأجنحة فاخرة بمستوى لا يُقارن. للتجربة اللي تستحق كل قرش.', 'The most luxurious in Dahab — 5 stars on a private sandy beach in the enchanting Laguna. Half Board at a world-class seaside restaurant, with luxurious villas and suites at an incomparable level. For the experience worth every penny.', ARRAY['https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 4.9, 'اللاجونا · 5 نجوم · دهب', 'اللاجونا · 5 نجوم · دهب', 'Laguna · 5 Stars · Dahab', 28.5092, 34.5185, ARRAY['5 نجوم', 'Half Board', 'شاطئ خاص', 'فيلات فاخرة', 'مطعم عالمي', 'مسبح']::TEXT[], ARRAY['5 Stars', 'Half Board', 'Private Beach', 'Luxury Villas', 'World-Class Restaurant', 'Pool']::TEXT[], 3000, 12100, 15800, true);
INSERT INTO sinai_trips (name_ar, name_en, description_ar, description_en, category_ar, category_en, images, duration, duration_en, price, includes_ar, includes_en, is_active) VALUES ('سنوركلينج في البلوهول وأبو جالوم', 'Snorkeling at Blue Hole & Abu Galum', 'رحلة بحرية ليوم كامل لأشهر مواقع الغوص والسنوركلينج في العالم. البلوهول، أبو جالوم، و blue lagoon — ثلاثة أماكن ساحرة في يوم واحد مع غداء بدوي ومشروبات.', 'Full-day sea trip to the world''s most famous dive and snorkel sites. Blue Hole, Abu Galum, and Blue Lagoon — three stunning spots in one day with Bedouin lunch and drinks.', 'بحر ومغامرة', 'Adventure & Sea', ARRAY['https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 'https://images.unsplash.com/photo-1544551763-92ab472dec22?w=800&q=80']::TEXT[], 'يوم كامل (8 ساعات)', 'Full Day (8 hours)', 450, ARRAY['انتقالات من وإلى الفندق', 'معدات السنوركل', 'غداء بدوي', 'مرشد سياحي']::TEXT[], ARRAY['Hotel Transfers', 'Snorkeling Gear', 'Bedouin Lunch', 'Tour Guide']::TEXT[], true);
INSERT INTO sinai_trips (name_ar, name_en, description_ar, description_en, category_ar, category_en, images, duration, duration_en, price, includes_ar, includes_en, is_active) VALUES ('جبل موسى وسانت كاترين', 'Mount Sinai & St. Catherine', 'رحلة ليلية لمشاهدة الشروق من أعلى قمة في سيناء. تسلق جبل موسى ليلاً، مشاهدة الشروق، ثم زيارة دير سانت كاترين التاريخي. تجربة روحانية لا تُنسى.', 'Night trip to watch sunrise from Sinai''s highest peak. Night climb of Mount Sinai, sunrise viewing, then visit the historic St. Catherine Monastery. An unforgettable spiritual experience.', 'ديني وجبلي', 'Religious & Mountain Trek', ARRAY['https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&q=80', 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80']::TEXT[], 'رحلة ليلية (12 ساعة)', 'Night Trip (12 hours)', 650, ARRAY['انتقالات بباص حديث', 'دليل بدوي مرخص', 'تذاكر دخول المحمية', 'مشروب دافئ']::TEXT[], ARRAY['Modern Bus Transfer', 'Licensed Bedouin Guide', 'Reserve Entry Tickets', 'Hot Drink']::TEXT[], true);
INSERT INTO sinai_trips (name_ar, name_en, description_ar, description_en, category_ar, category_en, images, duration, duration_en, price, includes_ar, includes_en, is_active) VALUES ('سفاري وادي قني والوشواشي', 'Wadi Qnai & Washwashi Safari', 'مغامرة صحراوية وسط جبال سيناء الملونة. جيب 4x4 لوديان قني والوشواشي، سباحة في عيون مائية طبيعية بين الجبال، وغداء بدوي تحت الشمس.', 'Desert adventure through Sinai''s colored mountains. 4x4 jeep to Wadi Qnai and Washwashi, swimming in natural springs between mountains, and Bedouin lunch under the sun.', 'سفاري وجواهر مخفية', 'Safari & Hidden Gems', ARRAY['https://images.unsplash.com/photo-1451337516015-6b6e9a44a8a3?w=800&q=80', 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&q=80']::TEXT[], 'نصف يوم (5 ساعات)', 'Half Day (5 hours)', 500, ARRAY['سيارات جيب 4x4', 'دليل خبير', 'مياه ومشروبات', 'غداء بدوي']::TEXT[], ARRAY['4x4 Jeep Transportation', 'Expert Guide', 'Water & Drinks', 'Bedouin Lunch']::TEXT[], true);
INSERT INTO community_posts (title_ar, title_en, content_ar, content_en, category, image_url, sort_order, is_pinned, is_published) VALUES ('ليه دهب مختلفة عن أي مكان تاني في مصر', 'Why Dahab is Different from Anywhere Else in Egypt', 'دهب مش مجرد مدينة ساحلية — دي حالة. مزيج فريد من البحر والجبل والصحراء في مكان واحد. الجو مختلف، الناس مختلفة، والطاقة مختلفة. في البوست ده هنحكي عن اللي بيخلي دهب مميزة عن أي مكان تاني.', 'Dahab isn''t just a coastal town — it''s a state of mind. A unique blend of sea, mountain, and desert in one place. The vibe is different, the people are different, the energy is different. In this post we tell you what makes Dahab unlike anywhere else.', 'blog', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 1, true, true);
INSERT INTO community_posts (title_ar, title_en, content_ar, content_en, category, image_url, sort_order, is_pinned, is_published) VALUES ('منطقة وادي الوشواشي — الجوهرة المخفية', 'Wadi Washwashi — The Hidden Gem', 'وادي سري في قلب جبال سيناء، ما بين مياه فيروزية وصخور جرانيتية ملونة. المكان ده مش كل الناس تعرفه، وده اللي بيخليه مميز. في البوست ده هنشرح إزاي توصل له وأفضل وقت تزوره.', 'A secret valley in the heart of Sinai''s mountains, between turquoise waters and colored granite rocks. Not everyone knows this place, and that''s what makes it special. In this post we explain how to get there and the best time to visit.', 'hidden-gems', 'https://images.unsplash.com/photo-1451337516015-6b6e9a44a8a3?w=800&q=80', 2, false, true);
INSERT INTO community_posts (title_ar, title_en, content_ar, content_en, category, image_url, sort_order, is_pinned, is_published) VALUES ('أول مرة في دهب؟ دليلك الكامل', 'First Time in Dahab? Your Complete Guide', 'لو دي أول مرة ليك في دهب، البوست ده معمول عشانك. من أفضل وقت للزيارة، لإزاي توصل، لأفضل الأماكن للإقامة، وأهم الأنشطة اللي متضيعش. دليل شامل بيجاوب على كل أسئلتك.', 'If this is your first time in Dahab, this post was made for you. From the best time to visit, to how to get there, to the best places to stay, and the must-do activities. A comprehensive guide that answers all your questions.', 'dahab-guide', 'https://images.unsplash.com/photo-1573843981267-be1999ff37cd?w=800&q=80', 3, false, true);
